<?phpsession_start();if (!isset($_SESSION['admin_connecte']) || $_SESSION['admin_connecte'] !== true) {    header("Location: login.php");    exit();}// Sécurité Sessionif (!isset($_SESSION['id_admin'])) {    die("Erreur de session : Veuillez vous déconnecter et vous reconnecter.");}$id_utilisateur = $_SESSION['id_admin'];// ==========================================// 1. LECTURE DES SEUILS DYNAMIQUES (config.json)// ==========================================$fichier_config = 'config.json';$seuil_froid = 34.0;$seuil_chaud = 35.5;if (file_exists($fichier_config)) {    $config_actuelle = json_decode(file_get_contents($fichier_config), true);    if(isset($config_actuelle['seuil_froid'])) $seuil_froid = floatval($config_actuelle['seuil_froid']);    if(isset($config_actuelle['seuil_chaud'])) $seuil_chaud = floatval($config_actuelle['seuil_chaud']);}// ==========================================// 2. CONNEXION À LA BDD ET LOGIQUE DE TRI// ==========================================$host = "127.0.0.1";$dbname = "madeb2677953_2zjnm";$user = "madeb2677953_2zjnm";$pass = "wddzero3it";$mes_ruches = [];$total_ruches = 0;try {    $pdo = new PDO("mysql:host=$host;dbname=$dbname;charset=utf8", $user, $pass);    $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);    // --- 0. QUELLES RUCHES POSSÈDE L'UTILISATEUR ? ---    $stmt_ruches = $pdo->prepare("SELECT id_ruche FROM ruche WHERE id_admin = :id_admin");    $stmt_ruches->execute(['id_admin' => $id_utilisateur]);    while ($row = $stmt_ruches->fetch(PDO::FETCH_ASSOC)) {        $mes_ruches[] = $row['id_ruche'];    }    $total_ruches = count($mes_ruches);    // --- A. Données de LUCAS (ID 1) -> Utilisées pour la Météo Globale ---    $stmt_lucas = $pdo->query("SELECT temperature, humidite FROM mesures WHERE id_ruche = 1 ORDER BY id_mesure DESC LIMIT 1");    $data_lucas = $stmt_lucas->fetch();    $temp_ext = $data_lucas ? floatval($data_lucas['temperature']) : 26.5;    $hum_ext = $data_lucas ? floatval($data_lucas['humidite']) : 65.0;    // 🧠 IA MÉTÉO    if ($hum_ext >= 80) {        $meteo_txt = "PLUVIEUX";        $meteo_icon = "fas fa-cloud-showers-heavy";        $meteo_color = "var(--neon-blue)";    } elseif ($hum_ext >= 60) {        $meteo_txt = "NUAGEUX";        $meteo_icon = "fas fa-cloud";        $meteo_color = "#94a3b8";     } else {        $meteo_txt = "ENSOLEILLÉ";        $meteo_icon = "fas fa-sun";        $meteo_color = "var(--neon-gold)";    }    // --- B. Données de BETA (ID 2) ---    $stmt_julien = $pdo->query("SELECT temperature, humidite, poids FROM mesures WHERE id_ruche = 2 ORDER BY id_mesure DESC LIMIT 1");    $data_julien = $stmt_julien->fetch();    $temp_beta = $data_julien ? floatval($data_julien['temperature']) : 30.2;     $hum_beta = $data_julien ? floatval($data_julien['humidite']) : 55.0;     $poids_beta = $data_julien ? floatval($data_julien['poids']) : 38.5;} catch(PDOException $e) {    $temp_ext = 0; $hum_ext = 0;     $meteo_txt = "ERREUR BDD"; $meteo_icon = "fas fa-exclamation-triangle"; $meteo_color = "red";    $temp_beta = 0; $hum_beta = 0; $poids_beta = 0;}?><!DOCTYPE html><html lang="fr"><head>    <meta charset="UTF-8">    <title>BEE WEB // DASHBOARD</title>    <meta http-equiv="refresh" content="30">    <link rel="stylesheet" href="style_app.css">    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">    <style>        .empty-state { text-align: center; padding: 50px 20px; border: 1px dashed var(--neon-blue); border-radius: 8px; background: rgba(14, 165, 233, 0.05); }        .empty-state i { font-size: 4rem; color: #334155; margin-bottom: 20px; }        .empty-state h3 { color: var(--neon-blue); margin-bottom: 10px; }        .empty-state p { color: var(--text-dim); margin-bottom: 25px; font-size: 0.9rem; }                /* Style pour la carte d'ajout de ruche */        .add-hive-card {            border: