ue); transition: 0.3s;">                        <div style="display:flex; justify-content:space-between; margin-bottom:20px;">                            <div>                                <h3 style="margin:0; font-size:1.2rem;">ALPHA-01</h3>                                <span style="font-size:0.75rem; color:var(--text-dim);">ID: 1 (PASSERELLE MÈRE)</span>                            </div>                            <span id="badge-alpha" class="badge badge-ok"><i class="fas fa-check-circle"></i> NOMINAL</span>                        </div>                        <div style="display:grid; grid-template-columns: 1fr 1fr 1fr; gap:10px; margin-bottom:20px;">                            <div style="background:rgba(255,255,255,0.03); padding:10px; border-radius:8px; text-align:center;">                                <i class="fas fa-temperature-half" style="color:var(--neon-blue); margin-bottom:5px;"></i>                                <div style="font-size:0.6rem; color:var(--text-dim);">TEMP. INT.</div>                                <div style="font-size:1.1rem; font-weight:bold;">34.8°C</div>                            </div>                            <div style="background:rgba(255,255,255,0.03); padding:10px; border-radius:8px; text-align:center;">                                <i class="fas fa-droplet" style="color:var(--neon-blue); margin-bottom:5px;"></i>                                <div style="font-size:0.6rem; color:var(--text-dim);">HUMIDITÉ</div>                                <div style="font-size:1.1rem; font-weight:bold;">52%</div>                            </div>                            <div style="background:rgba(255,255,255,0.03); padding:10px; border-radius:8px; text-align:center;">                                <i class="fas fa-weight-hanging" style="color:var(--neon-blue); margin-bottom:5px;"></i>                                <div style="font-size:0.6rem; color:var(--text-dim);">POIDS</div>                                <div style="font-size:1.1rem; font-weight:bold;">42.5kg</div>                            </div>                        </div>                        <a href="monitoring.php?hive=alpha" class="btn-cyber" style="text-align:center; text-decoration:none; display:block; transition: 0.3s;">                            <i class="fas fa-chart-line"></i> VOIR DÉTAILS                        </a>                    </div>                    <?php endif; ?>                    <?php if (in_array(2, $mes_ruches)): ?>                    <div id="card-beta" class="glass" style="border-top: 3px solid var(--neon-blue); transition: 0.3s;">                        <div style="display:flex; justify-content:space-between; margin-bottom:20px;">                            <div>                                <h3 style="margin:0; font-size:1.2rem;">BETA-VORTEX</h3>                                <span style="font-size:0.75rem; color:var(--text-dim);">ID: 2 (UNITÉ FILLE - LIVE)</span>                            </div>                            <span id="badge-beta" class="badge badge-ok"><i class="fas fa-check-circle"></i> NOMINAL</span>                        </div>                                                <div id="warning-beta" style="background:rgba(239, 68, 68, 0.1); padding:10px; border-radius:6px; margin-bottom:20px; border:1px solid rgba(239, 68, 68, 0.3); color:var(--neon-red); font-size:0.85rem; display:none; align-items:center; gap:10px;">                            <i id="icon-warning-beta" class="fas fa-fire"></i> <span id="text-warning-beta">DANGER</span>                        </div>                        <div style="display:grid; grid-template-columns: 1fr 1fr 1fr; gap:10px; margin-bottom:20px;">                            <div id="box-temp-beta" style="background:rgba(255,255,255,0.03); padding:10px; border-radius:8px; text-align:center; transition: 0.3s;">                                <i id="icon-temp-beta" class="fas fa-temperature-half" style="color:var(--neon-green); margin-bottom:5px;"></i>                                <div style="font-size:0.6rem; color:var(--text-dim);">TEMP. INT.</div>                                <div id="temp-beta" style="font-size:1.1rem; font-weight:bold; transition: 0.3s;"><?php echo $temp_beta; ?>°C</div>                            </div>                            <div style="background:rgba(255,255,255,0.03); padding:10px; border-radius:8px; text-align:center;">                                <i class="fas fa-droplet-percent" style="color:var(--neon-green); margin-bottom:5px;"></i>                                <div style="font-size:0.6rem; color:var(--text-dim);">HUMIDITÉ</div>                                <div style="font-size:1.1rem; font-weight:bold;"><?php echo $hum_beta; ?>%</div>                            </div>                            <div style="background:rgba(255,255,255,0.03); padding:10px; border-radius:8px; text-align:center;">                                <i class="fas fa-balance-scale" style="color:var(--neon-green); margin-bottom:5px;"></i>                                <div style="font-size:0.6rem; color:var(--text-dim);">POIDS</div>                                <div style="font-size:1.1rem; font-weight:bold;"><?php echo $poids_beta; ?>kg</div>                            </div>                        </div>                        <a id="btn-beta" href="monitoring.php?hive=beta" class="btn-cyber" style="text-align:center; text-decoration:none; display:block; transition: 0.3s;">                            <i class="fas fa-search"></i> DIAGNOSTIC                        </a>                    </div>                    <?php endif; ?>                <?php else: ?>                    <div class="empty-state glass" style="grid-column: 1 / -1;">                        <i class="fas fa-box-open"></i>                        <h3>AUCUNE RUCHE DÉTECTÉE</h3>                        <p>Votre flotte apiary est actuellement vide.</p>                    </div>                <?php endif; ?>                <div class="add-hive-card" onclick="openModal()">                    <i class="fas fa-plus-circle"></i>                    <h3>AJOUTER UNE RUCHE</h3>                </div>            </div>        </main>    </div>    <div id="adminModal" class="modal-overlay">        <div class="modal-content">            <i class="fas fa-user-shield" style="font-size: 4rem; color: var(--neon-blue); margin-bottom: 20px;"></i>            <h2 style="color: var(--neon-blue); margin-top: 0; font-size: 1.5rem;">AUTORISATION REQUISE</h2>            <p style="color: var(--text-dim); margin-bottom: 20px; line-height: 1.5;">                Pour des raisons de sécurité matérielle et de chiffrement des données, l'ajout d'une nouvelle unité physique doit être validé par le système central.            </p>            <div style="background: rgba(14, 165, 233, 0.1); padding: 15px; border-radius: 8px; margin-bottom: 25px; border: 1px dashed var(--neon-blue);">                <p style="margin: 0; color: white; font-size: 0.9rem;">Veuillez contacter l'administrateur système :</p>                <a href="mailto:melainaprojet@gmail.com" style="color: var(--neon-gold); font-weight: bold; text-decoration: none; font-size: 1.1rem; display: inline-block; margin-top: 5px;">                    <i class="fas fa-envelope"></i> melainaprojet@gmail.com                </a>            </div>            <button onclick="closeModal()" class="btn-cyber" style="width: 100%; border-color: #64748b; color: white;">                <i class="fas fa-times"></i> FERMER            </button>        </div>    </div>    <script>        const seuilFroid = <?php echo $seuil_froid; ?>;        const seuilChaud = <?php echo $seuil_chaud; ?>;        const valTempBeta = <?php echo $temp_beta; ?>;        // Fonction pour gérer l'ouverture et fermeture de la popup        function openModal() {            document.getElementById('adminModal').style.display = 'flex';        }        function closeModal() {            document.getElementById('adminModal').style.display = 'none';        }        function evaluerAlertes() {            let alertesCount = 0;            // Toujours nominal pour l'unité mère            activerAlerte('alpha', 'nominal');            // Évaluation de l'unité Live (Beta)            if(valTempBeta >= seuilChaud) {                alertesCount++;                 activerAlerte('beta', 'chaud');            } else if (valTempBeta <= seuilFroid && valTempBeta > 0) {                alertesCount++;                 activerAlerte('beta', 'froid');            } else {                activerAlerte('beta', 'nominal');            }            // Mise à jour de la cloche en haut            document.getElementById('alert-count').innerText = "0" + alertesCount;            if(alertesCount > 0) {                document.getElementById('alert-box').style.border = "1px solid var(--neon-red)";                document.getElementById('alert-title').style.color = "var(--neon-red)";                document.getElementById('alert-count').style.color = "var(--neon-red)";                document.getElementById('alert-bell').className = "fas fa-bell blink";                document.getElementById('alert-bell').style.color = "var(--neon-red)";            }        }        function activerAlerte(hive, etat) {            const card = document.getElementById(`card-${hive}`);            if(!card) return;             const badge = document.getElementById(`badge-${hive}`);            const tempVal = document.getElementById(`temp-${hive}`);            const tempBox = document.getElementById(`box-temp-${hive}`);            const tempIcon = document.getElementById(`icon-temp-${hive}`);            const banner = document.getElementById(`warning-${hive}`);            const textBanner = document.getElementById(`text-warning-${hive}`);            const iconBanner = document.getElementById(`icon-warning-${hive}`);            const btn = document.getElementById(`btn-${hive}`);            if(etat === 'chaud') {                card.style.borderTop = "3px solid var(--neon-red)";                card.style.boxShadow = "0 0 20px rgba(239, 68, 68, 0.1)";                badge.className = "badge badge-danger blink";                badge.innerHTML = `<i class="fas fa-fire"></i> SURCHAUFFE`;                if(tempVal) tempVal.style.color = "var(--neon-red)";                if(tempIcon) { tempIcon.className = "fas fa-temperature-arrow-up"; tempIcon.style.color = "var(--neon-red)"; }                if(tempBox) { tempBox.style.background = "rgba(239,68,68,0.05)"; tempBox.style.border = "1px solid rgba(239,68,68,0.2)"; }                if(banner) { banner.style.display = "flex"; banner.style.color = "var(--neon-red)"; banner.style.borderColor = "rgba(239, 68, 68, 0.3)"; banner.style.background = "rgba(239, 68, 68, 0.1)"; }                if(textBanner) textBanner.innerText = "DANGER : SURCHAUFFE COLONIE";                if(iconBanner) iconBanner.className = "fas fa-fire";                if(btn) { btn.style.borderColor = "var(--neon-red)"; btn.style.color = "var(--neon-red)"; }                        } else if (etat === 'froid') {                card.style.borderTop = "3px solid #38bdf8";                card.style.boxShadow = "0 0 20px rgba(56, 189, 248, 0.1)";                badge.className = "badge blink";                badge.style.background = "rgba(56, 189, 248, 0.2)";                badge.style.color = "#38bdf8";                badge.innerHTML = `<i class="fas fa-snowflake"></i> HYPOTHERMIE`;                if(tempVal) tempVal.style.color = "#38bdf8";                if(tempIcon) { tempIcon.className = "fas fa-temperature-arrow-down"; tempIcon.style.color = "#38bdf8"; }                if(tempBox) { tempBox.style.background = "rgba(56, 189, 248, 0.05)"; tempBox.style.border = "1px solid rgba(56, 189, 248, 0.2)"; }                if(banner) { banner.style.display = "flex"; banner.style.color = "#38bdf8"; banner.style.borderColor = "rgba(56, 189, 248, 0.3)"; banner.style.background = "rgba(56, 189, 248, 0.1)"; }                if(textBanner) textBanner.innerText = "ALERTE : TEMPÉRATURE CRITIQUE (BASSE)";                if(iconBanner) iconBanner.className = "fas fa-snowflake";                if(btn) { btn.style.borderColor = "#38bdf8"; btn.style.color = "#38bdf8"; }            } else {                card.style.borderTop = "3px solid var(--neon-blue)";            }        }        evaluerAlertes();    </script></body></html>